"""Verifier rerun request generated by reviewer actions."""

from __future__ import annotations

import hashlib
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any


@dataclass(frozen=True)
class VerifierRerunRequest:
    rule_id: str
    source_action_id: str
    candidate_rule_fields: dict[str, Any]
    reason: str = "reviewer_action_requires_verifier_rerun"
    approved_evidence_ids: tuple[str, ...] = ()
    resolved_dependency_ids: tuple[str, ...] = ()
    table_lineage: dict[str, Any] | None = None
    reviewer_note: str = ""
    status: str = "pending"
    created_at: str = ""
    metadata: dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not self.rule_id:
            raise ValueError("verifier rerun request requires rule_id")
        if self.status not in {"pending", "submitted", "complete", "failed"}:
            raise ValueError(f"unknown verifier rerun request status: {self.status}")
        if not self.created_at:
            object.__setattr__(self, "created_at", datetime.now(timezone.utc).isoformat())

    @property
    def request_id(self) -> str:
        return "verifier_rerun_" + _stable_id(self.rule_id, self.source_action_id, self.created_at)

    def to_dict(self) -> dict[str, Any]:
        return {
            "request_id": self.request_id,
            "rule_id": self.rule_id,
            "source_action_id": self.source_action_id,
            "candidate_rule_fields": dict(self.candidate_rule_fields),
            "reason": self.reason,
            "approved_evidence_ids": list(self.approved_evidence_ids),
            "resolved_dependency_ids": list(self.resolved_dependency_ids),
            "table_lineage": self.table_lineage,
            "reviewer_note": self.reviewer_note,
            "status": self.status,
            "created_at": self.created_at,
            "metadata": dict(self.metadata),
        }

    @classmethod
    def from_dict(cls, payload: dict[str, Any]) -> "VerifierRerunRequest":
        data = dict(payload or {})
        return cls(
            rule_id=str(data.get("rule_id") or ""),
            source_action_id=str(data.get("source_action_id") or ""),
            candidate_rule_fields=dict(data.get("candidate_rule_fields") or {}),
            reason=str(data.get("reason") or "reviewer_action_requires_verifier_rerun"),
            approved_evidence_ids=tuple(str(item) for item in data.get("approved_evidence_ids", [])),
            resolved_dependency_ids=tuple(str(item) for item in data.get("resolved_dependency_ids", [])),
            table_lineage=data.get("table_lineage"),
            reviewer_note=str(data.get("reviewer_note") or ""),
            status=str(data.get("status") or "pending"),
            created_at=str(data.get("created_at") or ""),
            metadata=dict(data.get("metadata") or {}),
        )


def _stable_id(*parts: Any, length: int = 16) -> str:
    text = "|".join(str(part or "") for part in parts)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:length]

